const oldFile = {
  name: "greeting.ts",
  contents: "export function greet(name: string) {\n  return `Hello, ${name}`;\n}\n",
};
const newFile = {
  name: "greeting.ts",
  contents:
    'export function greet(name: string = "world") {\n  const greeting = `Welcome, ${name}!`;\n  return greeting;\n}\n',
};
export { oldFile, newFile };

import { useState } from "react";
import { DiffView } from "@/registry/erbium/blocks/diff-view";
import { Button } from "@/registry/erbium/ui/button";
import { oldFile, newFile } from "../examples/files";

export default function Example() {
  const [reversed, setReversed] = useState(false);
  return (
    <div className="grid w-full max-w-4xl gap-4">
      <Button className="w-fit" size="sm" variant="outline" onClick={() => setReversed(!reversed)}>
        Swap file versions
      </Button>
      <DiffView oldFile={reversed ? newFile : oldFile} newFile={reversed ? oldFile : newFile} />
    </div>
  );
}
